 const string Akte="versicherung-2026";
 static byte[] Text(string s)=>Encoding.UTF8.GetBytes(s);
 [Fact] public void NotizHatBetreffHistorieKonfliktschutzUndWiederherstellung(){
  var b=new Aktenbestand();var n=b.NotizSpeichern(Akte,null,new("Rückfrage","Erster Inhalt"));
  Assert.Equal(1,n.Version);Assert.Equal(n.ErstelltAm,n.GeaendertAm);Assert.NotEmpty(n.Autor);
  var neu=b.NotizSpeichern(Akte,n.Id,new("Antwort","Zweiter Inhalt",1));
  Assert.Equal(n.ErstelltAm,neu.ErstelltAm);Assert.Equal(2,neu.Historie.Count);Assert.Equal("Erster Inhalt",neu.Historie[0].Inhalt);
  Assert.Equal(409,Assert.Throws<Arbeitsfehler>(()=>b.NotizSpeichern(Akte,n.Id,new("Veraltet","Nein",1))).Status);
  var weg=b.NotizEntfernen(Akte,n.Id,2);Assert.True(weg.Entfernt);Assert.Single(b.Lesen(Akte).Notizen);
  Assert.Throws<Arbeitsfehler>(()=>b.NotizSpeichern(Akte,n.Id,new("Verboten","Nein",3)));
  var wieder=b.NotizEntfernen(Akte,n.Id,3,true);Assert.False(wieder.Entfernt);Assert.Equal(4,wieder.Historie.Count);
  Assert.Throws<Arbeitsfehler>(()=>b.NotizSpeichern(Akte,null,new(" ","Inhalt")));
  Assert.Throws<Arbeitsfehler>(()=>b.NotizSpeichern(Akte,null,new("Titel",new string('a',10001))));
 }
 [Fact] public void VieleEintraegeUndKorrespondenzNutzenDieselbeAkte(){
  var b=new Aktenbestand();for(int i=0;i<50;i++)b.NotizSpeichern(Akte,null,new($"Notiz {i}","Inhalt"));
  for(int i=0;i<80;i++)b.Hinzufuegen(Text($"Dokument {i}"),$"Anlage-{i}.txt","text/plain",Akte);
  var d=b.Lesen(Akte).Dokumente[0];for(int i=0;i<100;i++)b.KorrespondenzSpeichern(Akte,new($"Schreiben {i}","Inhalt","Brief",d.Id));
  var a=b.Lesen(Akte);Assert.Equal(50,a.Notizen.Count);Assert.Equal(80,a.Dokumente.Count);Assert.Equal(100,a.Korrespondenz.Count);
  Assert.Throws<Arbeitsfehler>(()=>b.KorrespondenzSpeichern("demo-nord-rechnung-002",new("Fremd","Inhalt","E-Mail",d.Id)));
 }
 [Fact] public void ZentraleDateiHatMehrereVerweiseAberNurEinOriginal(){
  var b=new Aktenbestand();var bytes=Text("Gleiches Original");var d=b.Hinzufuegen(bytes,"Brief.txt","text/plain",null);bytes[0]=0;
  Assert.Equal("Gleiches Original",b.Text(d.Id));Assert.Single(b.Eingang());
  var z=b.Zuordnen(d.Id,new(Akte,null,"Versicherung",null,1));Assert.Empty(b.Eingang());
  var d2=b.Hinzufuegen(Text("Gleiches Original"),"Umbenannt.txt","text/plain","demo-nord-rechnung-002");Assert.Equal(d.Id,d2.Id);Assert.Equal(2,d2.Vorgaenge.Count);
  Assert.Throws<Arbeitsfehler>(()=>b.Zuordnen(d.Id,new(Akte,null,"Rechnung",null,1)));
  Assert.Equal(64,b.Technik(d.Id).DateiHash.Length);Assert.Equal("Dateiauswahl",b.Technik(d.Id).Quelle);
  var original=b.Bytes(d.Id);original[0]=0;Assert.NotEqual(0,b.Bytes(d.Id)[0]);
  Assert.Throws<Arbeitsfehler>(()=>b.Bytes(d.Id,"unbekannt"));
  var Eingang=b.Hinzufuegen(Text("Neuer Vorgang"),"Vertrag.txt","text/plain",null);
  var zu=b.Zuordnen(Eingang.Id,new(null,"Vertragsprüfung","Vertrag","DEMO-NORD",1));Assert.Equal("Vertragsprüfung",b.Lesen(zu.Vorgaenge[0]).Vorgang.Titel);
 }
 [Theory][InlineData("Übernehmen",2)][InlineData("Zusätzlich speichern",2)][InlineData("Ignorieren",1)]
 public void KontakteWerdenNurNachPruefungMitHistorieGeaendert(string aktion,int aktiv){
  var b=new Aktenbestand();var d=b.Hinzufuegen(Text("Telefon: +49 30 23125 088\nE-Mail: neu@example.invalid\nAnsprechpartner: Kim Beispiel"),"Neue-Kontaktdaten.txt","text/plain",Akte);
  var v=b.Lesen(Akte).Kontaktvorschlaege.Single(v=>v.Art=="Telefon");Assert.Equal("Zur Prüfung",v.Status);Assert.Contains("66969",v.Bisher);
  var vor=b.Kontakte().Single(k=>k.Id==v.FirmaId);Assert.DoesNotContain(vor.Werte,w=>w.Wert==v.Neu);
  Assert.Throws<Arbeitsfehler>(()=>b.KontaktEntscheiden(v.Id,new(aktion,0)));
  var nach=b.KontaktEntscheiden(v.Id,new(aktion,v.Kontaktversion));Assert.Equal(aktiv,nach.Werte.Count(w=>w.Art=="Telefon"&&w.Aktiv));
  Assert.Contains(nach.Werte,w=>w.Wert==v.Bisher&&w.Aktiv);var h=Assert.Single(nach.Historie);Assert.Equal(d.Id,h.DokumentId);Assert.NotEmpty(h.Benutzer);Assert.Equal(aktion,h.Aktion);
  Assert.Throws<Arbeitsfehler>(()=>b.KontaktEntscheiden(v.Id,new(aktion,nach.Version)));
 }
 [Theory][InlineData("s.exe","text/plain")][InlineData("s.pdf","text/plain")][InlineData("../s.txt","text/plain")][InlineData("s.xlsm","")]
 public void GefaehrlicheOderFalscheDateitypenWerdenAbgewiesen(string name,string mime)=>Assert.Throws<Arbeitsfehler>(()=>new Dokumentpruefung().Pruefen(Text("Text"),name,mime));
 [Fact]public void DateigrenzenUndAktivePdfWerdenAbgewiesen(){var p=new Dokumentpruefung();Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(new byte[2097153],"gross.txt",""));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen([],"leer.txt",""));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Text("%PDF-1.4 /J#61vaScript %%EOF"),"aktiv.pdf","application/pdf"));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen([255,255],"kaputt.txt","text/plain"));}
 static byte[] Office(string teil,string xml,string extras="") {using var ms=new MemoryStream();using(var z=new ZipArchive(ms,ZipArchiveMode.Create,true)){foreach(var(n,t)in new[]{("[Content_Types].xml","<Types/>"),("_rels/.rels","<Relationships>"+extras+"</Relationships>"),(teil,xml)}){using var w=new StreamWriter(z.CreateEntry(n).Open());w.Write(t);}}return ms.ToArray();}
 [Fact]public void OfficeIstAnhangOhneAusfuehrungUndDocxHatNurText(){var p=new Dokumentpruefung();var d=p.Pruefen(Office("word/document.xml","<document><t>Telefon: +49 30 23125 088</t></document>"),"Brief.docx","");Assert.Contains("Telefon:",d.Text);Assert.Equal("download",d.Vorschau);var x=p.Pruefen(SynthetischeArbeitsmappe.Bauen(SynthetischeArbeitsmappe.Teile(SynthetischeArbeitsmappe.Zeile())),"Daten.xlsx","");Assert.Empty(x.Text);Assert.Equal("download",x.Vorschau);Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Office("word/document.xml","<document/>","<Relationship TargetMode='External' Target='https://example.invalid'/>"),"Brief.docx",""));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Office("word/document.xml","<!DOCTYPE doc [<!ENTITY ext SYSTEM 'file:///C:/geheim'>]><doc>&ext;</doc>"),"Brief.docx",""));}
 sealed class Verweigern:ILesezugriff{public bool Erlaubt(string art,string id)=>false;}
 [Fact]public void SucheIstTeilwortBasiertBegrenztUndFiltertRechteUndModule(){var b=new Aktenbestand();b.Hinzufuegen(Text("Brief"),"Kieselanker-Beitrag.txt","text/plain",Akte);var s=new AktenSuche(b,()=>DemoDaten.UebersichtErstellen(),new(),new LokalerDemozugriff());Assert.Empty(s.Finden("A"));Assert.Contains(s.Finden("Kiesel"),t=>t.Art=="Dokument");Assert.Empty(s.Finden("unfindbar"));Assert.Empty(new AktenSuche(b,()=>DemoDaten.UebersichtErstellen(),new(),new Verweigern()).Finden("Nord"));Assert.DoesNotContain(new AktenSuche(b,()=>DemoDaten.UebersichtErstellen(),new([]),new LokalerDemozugriff()).Finden("SYNTH"),t=>t.Art=="Rechnung");}
 [Fact]public void ScanOrdnerWartetAufStabileDateiIstIdempotentUndLoeschtNichts(){var pfad=Path.Combine(Path.GetTempPath(),"betrieb-scan-"+Guid.NewGuid());Directory.CreateDirectory(pfad);try{var b=new Aktenbestand();var a=new ScanOrdnerAdapter(pfad,b);File.WriteAllText(Path.Combine(pfad,"Brief.txt"),"Scan-Übung");a.Pruefen();Assert.Empty(b.Eingang());a.Pruefen();Assert.Single(b.Eingang());a.Pruefen();File.WriteAllText(Path.Combine(pfad,"Doppelt.txt"),"Scan-Übung");a.Pruefen();a.Pruefen();Assert.Single(b.Eingang());Assert.Equal(2,Directory.GetFiles(pfad).Length);File.WriteAllText(Path.Combine(pfad,"Fehler.exe"),"Nein");a.Pruefen();a.Pruefen();Assert.Equal(1,a.Status.Fehler);}finally{foreach(var datei in Directory.GetFiles(pfad))File.Delete(datei);Directory.Delete(pfad);}}
 [Fact]public async Task ApiVerlangtOriginPrueftDateienUndAktivierungServerseitig(){await using var app=ApiAnwendung.Erstellen([],0);await app.StartAsync();try{using var c=new HttpClient{BaseAddress=new Uri(app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single())};var ohne=await c.PostAsJsonAsync("/api/akten/versicherung-2026/notizen",new{betreff="Test",inhalt="Nein"});Assert.Equal(HttpStatusCode.Forbidden,ohne.StatusCode);c.DefaultRequestHeaders.Add("Origin",c.BaseAddress!.GetLeftPart(UriPartial.Authority));c.DefaultRequestHeaders.Add("X-Arbeitsaktion","1");var n=await c.PostAsJsonAsync("/api/akten/versicherung-2026/notizen",new{betreff="Test",inhalt="Ja"});n.EnsureSuccessStatusCode();using var f=new HttpRequestMessage(HttpMethod.Post,"/api/dokumenteingang"){Content=new ByteArrayContent(Text("Eingang"))};f.Content.Headers.ContentType=new("application/octet-stream");f.Headers.Add("X-Dateiname","Brief.txt");f.Headers.Add("X-Dateityp","text/plain");var r=await c.SendAsync(f);r.EnsureSuccessStatusCode();var doc=await r.Content.ReadFromJsonAsync<Aktendokument>();var download=await c.GetAsync($"/api/dokumente/{doc!.Id}/datei");download.EnsureSuccessStatusCode();Assert.Equal("nosniff",download.Headers.GetValues("X-Content-Type-Options").Single());}finally{await app.StopAsync();}
 await using var aus=ApiAnwendung.Erstellen([],0,module:new Arbeitsmodule([]));await aus.StartAsync();try{using var c=new HttpClient{BaseAddress=new Uri(aus.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single())};Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync("/api/akten")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync("/api/uebersicht")).StatusCode);}finally{await aus.StopAsync();}}

 [Fact]public void BilderWerdenGeprueftUndTexterkennungNichtVorgegeben(){
  var p=new Dokumentpruefung();var png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRz0AAAAASUVORK5CYII=");
  // PNG mit gültigen CRCs entsteht deterministisch im Test, ohne Bild-/OCR-Bibliothek.
  uint crc=0xffffffff;var pos=33;var len=System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(pos,4));foreach(var value in png.AsSpan(pos+4,len+4)){crc^=value;for(int i=0;i<8;i++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(png.AsSpan(pos+8+len,4),~crc);
  var ergebnis=p.Pruefen(png,"Scan.png","image/png");Assert.Equal("bild",ergebnis.Vorschau);Assert.Empty(ergebnis.Text);Assert.Contains("OCR nicht",ergebnis.Textmethode);
  var jpegOriginal=Convert.FromBase64String("");var jpeg=p.Pruefen(jpegOriginal,"Scan.JPG","image/jpeg");Assert.Equal("bild",jpeg.Vorschau);Assert.Empty(jpeg.Text);
  png[20]^=1;Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(png,"Kaputt.png","image/png"));
  Assert.Throws<Arbeitsfehler>(()=>p.Pruefen([255,216,255,192,0,2,255,217],"Kaputt.jpg","image/jpeg"));
 }
 [Fact]public void TiefeXmlUndUnerlaubteBeziehungenWerdenVorOfficeAusfuehrungAbgewiesen(){var p=new Dokumentpruefung();Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Office("word/document.xml",string.Concat(Enumerable.Repeat("<a>",40))+string.Concat(Enumerable.Repeat("</a>",40))),"Tief.docx",""));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Office("word/document.xml","<doc/>","<Relationship Target='https://example.invalid'/ >".Replace("/ >","/>")),"Extern.docx",""));Assert.Throws<Arbeitsfehler>(()=>p.Pruefen(Text("%PDF-1.4\nKein PDF\n%%EOF"),"Falsch.pdf","application/pdf"));}
